import { test, expect } from '@playwright/test'

// Smoke tests - critical app functionality that doesn't require authentication
// These run first and should pass in any environment

test.describe('App Basic Functionality', () => {
  test('app loads without crashing', async ({ page }) => {
    await page.goto('/')
    await page.waitForLoadState('domcontentloaded')

    // Should have a title
    const title = await page.title()
    expect(title).toBeTruthy()
    expect(title).toContain('BetterPack')

    // Should render substantial content
    const html = await page.locator('html').innerHTML()
    expect(html.length).toBeGreaterThan(100)

    // Check for no critical JavaScript errors
    const errorLogs: string[] = []
    page.on('console', msg => {
      if (msg.type() === 'error') {
        errorLogs.push(msg.text())
      }
    })

    await page.waitForTimeout(1000) // Give time for any JS errors to surface

    // Filter out common non-critical errors
    const criticalErrors = errorLogs.filter(error => 
      !error.includes('favicon') && 
      !error.includes('sw.js') &&
      !error.includes('Failed to register')
    )

    expect(criticalErrors).toHaveLength(0)
  })

  test('navigation links are present', async ({ page }) => {
    await page.goto('/')
    await page.waitForLoadState('domcontentloaded')

    // Look for authentication navigation elements
    const authLinks = [
      page.locator('a[href="/login"]'),
      page.locator('a[href="/signup"]'),
      page.getByRole('link', { name: /sign in|login/i }),
      page.getByRole('link', { name: /sign up|register/i }),
    ]

    // At least one auth link should be visible
    let hasVisibleAuthLink = false
    for (const link of authLinks) {
      if (await link.isVisible()) {
        hasVisibleAuthLink = true
        break
      }
    }

    expect(hasVisibleAuthLink).toBe(true)
  })

  test('responsive design works', async ({ page }) => {
    // Test mobile viewport
    await page.setViewportSize({ width: 375, height: 667 })
    await page.goto('/')
    await page.waitForLoadState('domcontentloaded')

    // Content should fit within viewport
    const body = page.locator('body')
    const boundingBox = await body.boundingBox()

    expect(boundingBox).toBeTruthy()
    expect(boundingBox!.width).toBeLessThanOrEqual(375)

    // Test desktop viewport
    await page.setViewportSize({ width: 1920, height: 1080 })
    await page.goto('/')
    await page.waitForLoadState('domcontentloaded')

    // Should still render properly
    const desktopBoundingBox = await body.boundingBox()
    expect(desktopBoundingBox).toBeTruthy()

    // Desktop should show more content (wider layout)
    expect(desktopBoundingBox!.width).toBeGreaterThan(375)
  })

  test('login page loads', async ({ page }) => {
    await page.goto('/login')
    await page.waitForLoadState('domcontentloaded')

    // Should have login form elements
    const emailField = page.locator('input[type="email"]')
    const passwordField = page.locator('input[type="password"]')
    const submitButton = page.locator('button[type="submit"]')

    await expect(emailField).toBeVisible()
    await expect(passwordField).toBeVisible()
    await expect(submitButton).toBeVisible()
  })

  test('signup page loads', async ({ page }) => {
    await page.goto('/signup')
    await page.waitForLoadState('domcontentloaded')

    // Should have signup form elements
    const emailField = page.locator('input[type="email"]')
    const passwordFields = page.locator('input[type="password"]')
    const submitButton = page.locator('button[type="submit"]')

    await expect(emailField).toBeVisible()
    await expect(passwordFields).toHaveCount(2) // Password + confirm password
    await expect(submitButton).toBeVisible()
  })
})

import { Button } from '@/components/ui/button'
import { User, LogOut, Mountain } from 'lucide-react'
import { Link } from 'react-router-dom'
import { useAuth } from '@/contexts/AuthContext'

interface AppHeaderProps {
  title?: string
  subtitle?: string
  icon?: React.ReactNode
  backTo?: string
  isDashboard?: boolean
  rightContent?: React.ReactNode
}

export function AppHeader({
  title = 'BetterPack',
  subtitle,
  icon,
  backTo = '/dashboard',
  isDashboard = false,
  rightContent
}: AppHeaderProps) {
  const { user, signOut } = useAuth()

  return (
    <header className="bg-white border-b border-border/40 sticky top-0 z-50 backdrop-blur-sm" role="banner">
      <nav className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8" role="navigation">
        <div className="flex justify-between items-center h-16">
          {/* Left section - Navigation */}
          <div className="flex items-center space-x-3 flex-1 min-w-0">
            {/* Mountain icon - always links to dashboard */}
            <Link
              to="/dashboard"
              className="p-2 sm:p-2 bg-primary/10 rounded-lg hover:opacity-80 transition-opacity flex-shrink-0 flex items-center justify-center"
            >
              <Mountain className="h-5 w-5 text-primary" />
            </Link>

            {/* Title - BetterPack on dashboard, page name elsewhere */}
            <h1 className="text-lg sm:text-xl font-semibold tracking-tight">
              {isDashboard ? 'BetterPack' : title}
            </h1>
            {subtitle && (
              <p className="text-xs text-muted-foreground truncate hidden sm:block">
                {subtitle}
              </p>
            )}
          </div>

          {/* Right section - Custom content and user actions */}
          <div className="flex items-center space-x-2 flex-shrink-0">
            {rightContent}

            {/* Always show user actions when logged in */}
            {user && (
              <div className="flex items-center space-x-1 sm:space-x-2">
                {/* Profile info - icon on mobile, full info on desktop */}
                <div className="flex items-center space-x-2 text-sm text-muted-foreground">
                  <User className="h-4 w-4" />
                  <span className="hidden sm:inline">{user.email}</span>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={signOut}
                  className="text-muted-foreground hover:text-foreground transition-colors duration-150 min-h-[44px]"
                >
                  <LogOut className="h-4 w-4 sm:mr-2" />
                  <span className="hidden sm:inline">Sign out</span>
                </Button>
              </div>
            )}
          </div>
        </div>
      </nav>
    </header>
  )
}

import { lazy, Suspense } from 'react'
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom'
import { QueryClientProvider } from '@tanstack/react-query'
import { ReactQueryDevtools } from '@tanstack/react-query-devtools'
import { AuthProvider, useAuth } from './contexts/AuthContext'
import { ProtectedRoute } from './components/auth/ProtectedRoute'
import { Toaster } from './components/ui/toaster'
import { Skeleton } from './components/ui/skeleton'
import { queryClient } from './lib/queryClient'
import './App.css'

// Lazy load heavy pages for code splitting
const LoginForm = lazy(() => import('./components/auth/LoginForm').then(m => ({ default: m.LoginForm })))
const SignupForm = lazy(() => import('./components/auth/SignupForm').then(m => ({ default: m.SignupForm })))
const Dashboard = lazy(() => import('./pages/Dashboard').then(m => ({ default: m.Dashboard })))
const GearCloset = lazy(() => import('./pages/GearCloset').then(m => ({ default: m.GearCloset })))

// Loading fallback component
function PageLoader() {
  return (
    <div className="min-h-screen bg-background flex items-center justify-center">
      <div className="space-y-4 w-full max-w-md">
        <Skeleton className="h-12 w-3/4 mx-auto" />
        <Skeleton className="h-64 w-full" />
        <Skeleton className="h-8 w-1/2 mx-auto" />
      </div>
    </div>
  )
}

function AppRoutes() {
  const { user } = useAuth()

  return (
    <Suspense fallback={<PageLoader />}>
      <Routes>
        <Route 
          path="/" 
          element={user ? <Navigate to="/dashboard" /> : <Navigate to="/login" />} 
        />
        <Route 
          path="/login" 
          element={user ? <Navigate to="/dashboard" /> : <LoginForm />} 
        />
        <Route 
          path="/signup" 
          element={user ? <Navigate to="/dashboard" /> : <SignupForm />} 
        />
        <Route
          path="/dashboard"
          element={
            <ProtectedRoute>
              <Dashboard />
            </ProtectedRoute>
          }
        />
        <Route
          path="/gear"
          element={
            <ProtectedRoute>
              <GearCloset />
            </ProtectedRoute>
          }
        />
      </Routes>
    </Suspense>
  )
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <Router>
        <AuthProvider>
          <AppRoutes />
          <Toaster />
        </AuthProvider>
      </Router>
      <ReactQueryDevtools initialIsOpen={false} />
    </QueryClientProvider>
  )
}

export default App

import { useState, useEffect } from 'react'
import { Link, useNavigate, useLocation } from 'react-router-dom'
import { useAuth } from '../../contexts/AuthContext'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Loader2, Mountain } from 'lucide-react'

export function LoginForm() {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [message, setMessage] = useState('')
  const { signIn } = useAuth()
  const navigate = useNavigate()
  const location = useLocation()

  useEffect(() => {
    const params = new URLSearchParams(location.search)
    const msg = params.get('message')
    if (msg) {
      setMessage(msg)
    }
  }, [location])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError('')
    setMessage('')
    setLoading(true)

    try {
      await signIn(email, password)
      navigate('/dashboard')
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-background py-12 px-4 sm:px-6 lg:px-8">
      <div className="w-full max-w-md space-y-8">
        <div className="text-center">
          <div className="flex justify-center mb-6">
            <div className="p-3 bg-primary/10 rounded-full">
              <Mountain className="h-10 w-10 text-primary" />
            </div>
          </div>
          <h1 className="text-4xl font-bold tracking-tight">BetterPack</h1>
          <p className="text-muted-foreground mt-3 text-lg">Your gear, organized.</p>
        </div>

        <Card className="border-border/40 shadow-sm">
          <CardHeader className="space-y-1 pb-6">
            <CardTitle className="text-2xl font-semibold tracking-tight">Welcome back</CardTitle>
            <CardDescription className="text-sm">
              Sign in to your account to manage your outdoor gear
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit}>
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="email">Email</Label>
                  <Input
                    id="email"
                    type="email"
                    placeholder="you@example.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    autoComplete="email"
                    disabled={loading}
                    className="transition-all duration-150 focus:ring-2 focus:ring-ring focus:ring-offset-2"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="password">Password</Label>
                  <Input
                    id="password"
                    type="password"
                    placeholder="••••••••"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    autoComplete="current-password"
                    disabled={loading}
                    className="transition-all duration-150 focus:ring-2 focus:ring-ring focus:ring-offset-2"
                  />
                </div>

                {message && (
                  <Alert>
                    <AlertDescription>{message}</AlertDescription>
                  </Alert>
                )}

                {error && (
                  <Alert variant="destructive">
                    <AlertDescription>{error}</AlertDescription>
                  </Alert>
                )}

                <Button 
                  type="submit" 
                  className="w-full bg-primary hover:bg-primary/90 transition-all duration-150 hover:scale-[1.02] active:scale-[0.98]" 
                  disabled={loading}
                >
                  {loading ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                      Signing in...
                    </>
                  ) : (
                    'Sign in'
                  )}
                </Button>
              </div>
            </form>
          </CardContent>
          <CardFooter className="flex justify-center pt-4">
            <p className="text-sm text-muted-foreground">
              Don't have an account?{' '}
              <Link to="/signup" className="text-primary hover:text-primary/80 hover:underline transition-colors duration-150 font-medium">
                Sign up
              </Link>
            </p>
          </CardFooter>
        </Card>
      </div>
    </div>
  )
}

