import { useState, lazy, Suspense } from 'react'
import { MobileFormDrawer } from '@/components/ui/mobile-form-drawer'
import { Skeleton } from '@/components/ui/skeleton'
import type { GearItem } from '@/types/database'

// Lazy load the heavy form component
const AddGearForm = lazy(() => import('./AddGearForm').then(m => ({ default: m.AddGearForm })))

interface AddGearFormWrapperProps {
  onAdd: (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => void
  onCancel?: () => void
  simplified?: boolean
  isOpen?: boolean
}

export function AddGearFormWrapper({ 
  onAdd, 
  onCancel, 
  simplified = false,
  isOpen = true
}: AddGearFormWrapperProps) {
  const [loading, setLoading] = useState(false)

  const handleAdd = async (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    setLoading(true)
    try {
      await onAdd(gear)
      // Don't close automatically - let parent handle it
    } finally {
      setLoading(false)
    }
  }

  return (
    <MobileFormDrawer
      isOpen={isOpen}
      onClose={onCancel || (() => {})}
      title="Add Gear"
      primaryAction={
        onCancel ? {
          label: 'Add Gear',
          onClick: () => {
            // Trigger form submission using data attribute selector
            const form = document.querySelector('form[data-gear-form]') as HTMLFormElement
            if (form) {
              form.requestSubmit()
            }
          },
          loading
        } : undefined

import { useEffect, useRef } from 'react'
import { Button } from '@/components/ui/button'
import { X } from 'lucide-react'

interface MobileFormDrawerProps {
  isOpen: boolean
  onClose: () => void
  title: string
  children: React.ReactNode
  primaryAction?: {
    label: string
    onClick: () => void
    disabled?: boolean
    loading?: boolean
  }
  secondaryAction?: {
    label: string
    onClick: () => void
    disabled?: boolean
  }
}

export function MobileFormDrawer({
  isOpen,
  onClose,
  title,
  children,
  primaryAction,
  secondaryAction
}: MobileFormDrawerProps) {
  const backdropRef = useRef<HTMLDivElement>(null)
  const drawerRef = useRef<HTMLDivElement>(null)

  // Handle escape key and body scroll prevention
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && isOpen) {
        onClose()
      }
    }

    if (isOpen) {
      document.addEventListener('keydown', handleKeyDown)

      // Prevent body scroll when drawer is open - use proper React pattern
      const originalOverflow = document.body.style.overflow
      const originalPaddingRight = document.body.style.paddingRight

      // Calculate scrollbar width to prevent layout shift
      const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth

    }
  }
}, [isOpen, onClose])

// Handle backdrop click
const handleBackdropClick = (event: React.MouseEvent) => {
  if (event.target === backdropRef.current) {
    onClose()
  }
}

if (!isOpen) return null

return (
  <div
    ref={backdropRef}
    className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50 md:items-center"
    onClick={handleBackdropClick}
    role="dialog"
    aria-modal="true"
    aria-labelledby="drawer-title"
  >
    <div
      ref={drawerRef}
      className="bg-white w-full max-h-[90vh] overflow-hidden flex flex-col mobile-form-drawer md:rounded-lg md:max-w-2xl"
      onClick={(e) => e.stopPropagation()}
    >
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b border-border/40 flex-shrink-0">
        <h2 id="drawer-title" className="text-lg font-semibold tracking-tight">{title}</h2>
        <Button
          variant="ghost"
          size="sm"
          onClick={onClose}
          className="p-1 h-8 w-8 rounded-full hover:bg-accent"
        >
          <X className="h-4 w-4" />
          <span className="sr-only">Close</span>
        </Button>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto">
        {children}
      </div>

      {/* Footer with actions */}
      {(primaryAction || secondaryAction) && (
        <div className="flex-shrink-0 p-4 border-t border-border/40 bg-background/95 backdrop-blur-sm">
          <div className="flex gap-3 justify-end md:justify-start">

      // Verify the page is still functional
      const body = page.locator('body')
      await expect(body).toBeVisible()
    })
  })
})

// Helper functions
async function findAddButton(page) {
  // First try to find the floating action button by its specific styling
  const fabButton = page.locator('button.rounded-full.shadow-lg').filter({
    has: page.locator('svg')
  }).first()

  if (await fabButton.count() > 0) {
    return fabButton
  }

  // Fallback: Look for any button containing a plus icon
  const plusButton = page.locator('button').filter({
    has: page.locator('svg')  // Has an SVG icon
  }).filter({
    hasText: /^$/ // No text content (icon-only)
  })

  if (await plusButton.count() > 0) {
    return plusButton.last() // Get the last one (likely the FAB)
  }

  // Final fallback: look for button with "Add" text if no gear items exist
  const addFirstButton = page.locator('button:has-text("Add First Item")')
  if (await addFirstButton.count() > 0) {
    return addFirstButton
  }

  throw new Error('Add button not found')
}

